{"content": "1|import { Injectable, Logger } from '@nestjs/common';
2|import { Cron, CronExpression } from '@nestjs/schedule';
3|import { PrismaService } from '../prisma/prisma.service';
4|import { BUSINESS_RULES } from '../../common/constants/business-rules';
5|
6|@Injectable()
7|export class PayrollAuditService {
8|  private readonly logger = new Logger(PayrollAuditService.name);
9|
10|  constructor(private readonly prisma: PrismaService) {}
11|
12|  /**
13|   * CronJob mensual (Día 1) para evaluar desempeño del mes anterior
14|   * y marcar penalizaciones consecutivas.
15|   */
16|  @Cron(CronExpression.EVERY_1ST_DAY_OF_MONTH_AT_MIDNIGHT)
17|  async runMonthlyAudit() {
18|    this.logger.log('Iniciando auditoría mensual de nómina y penalizaciones...');
19|    
20|    const drivers = await this.prisma.driver.findMany({
21|      where: { status: BUSINESS_RULES.STATUS.DRIVER.ACTIVE }
22|    });
23|
24|    for (const driver of drivers) {
25|      const levelKey = (driver.level || 'BASE') as keyof typeof BUSINESS_RULES.LEVELS;
26|      const levelConfig = BUSINESS_RULES.LEVELS[levelKey];
27|      
28|      // Obtener el último pago registrado (que debería contener las horas del mes que acaba de cerrar)
29|      const lastPayment = await this.prisma.payrollPayment.findFirst({
30|        where: { driverId: driver.id },
31|        orderBy: { createdAt: 'desc' },
32|      });
33|
34|      if (!lastPayment) continue;
35|
36|      const underGoal = lastPayment.transmissionHours < levelConfig.hours;
37|
38|      if (underGoal) {
39|        await this.prisma.driver.update({
40|          where: { id: driver.id },
41|          data: { 
42|            consecutiveMonthsUnderGoal: { increment: 1 } 
43|          }
44|        });
45|        this.logger.warn(`⚠️ Chofer ${driver.fullName}: ${lastPayment.transmissionHours}h vs Meta ${levelConfig.hours}h.`);
46|      } else {
47|        await this.prisma.driver.update({
48|          where: { id: driver.id },
49|          data: { consecutiveMonthsUnderGoal: 0 }
50|        });
51|      }
52|    }
53|    this.logger.log('Auditoría mensual completada.');
54|  }
55|
56|  /**
57|   * Aplica la lógica de penalización al monto base
58|   */
59|  async applyPenaltyLogic(driverId: string, amount: number) {
60|    const driver = await this.prisma.driver.findUnique({
61|      where: { id: driverId },
62|      select: { consecutiveMonthsUnderGoal: true, level: true }
63|    });
64|
65|    if (!driver) return { amount, penaltyApplied: false, penaltyAmount: 0 };
66|
67|    // Penalización del 10% (BASE.penalty) si lleva N+ meses incumpliendo.
68|    if (driver.consecutiveMonthsUnderGoal >= BUSINESS_RULES.PENALTY_THRESHOLD_MONTHS) {
69|      const penaltyRate = BUSINESS_RULES.LEVELS.BASE.penalty;
70|      const finalAmount = amount * (1 - penaltyRate);
71|      return {
72|        amount: finalAmount,
73|        penaltyApplied: true,
74|        penaltyAmount: amount * penaltyRate,
75|      };
76|    }
77|
78|    return { amount, penaltyApplied: false, penaltyAmount: 0 };
79|  }
80|}
