302|    try {
303|      await this.prisma.$executeRaw`SELECT refresh_active_campaigns();`;
304|      this.logger.log('✅ Active Campaigns Materialized View Refreshed');
305|    } catch (e) {
306|      this.logger.error('❌ Failed to refresh Materialized View', e.stack);
307|    }
308|  }
